import { drizzle } from 'drizzle-orm/node-sqlite';
import {
  applyProjectMetadataMigrations,
  type ProjectMetadataMigration,
} from './migrations';
import { createLogger } from '../../utils/logger';

const log = createLogger('ProjectMetadataStore');
const BUSY_TIMEOUT_MS = 5_000;

let databaseSyncCtor: (typeof import('node:sqlite'))['DatabaseSync'] | null =
  null;
const loadDatabaseSync = async (): Promise<
  (typeof import('node:sqlite'))['DatabaseSync']
> => {
  if (!databaseSyncCtor)
    databaseSyncCtor = (await import('node:sqlite')).DatabaseSync;
  return databaseSyncCtor;
};

export const openProjectMetadataDatabase = async ({
  databasePath,
  migrations,
}: {
  databasePath: string;
  migrations: readonly ProjectMetadataMigration[];
}) => {
  const DatabaseSync = await loadDatabaseSync();
  const client = new DatabaseSync(databasePath);
  try {
    client.exec('PRAGMA journal_mode = WAL');
    client.exec(`PRAGMA busy_timeout = ${BUSY_TIMEOUT_MS}`);
    const { fromVersion, toVersion } = applyProjectMetadataMigrations(client, {
      migrations,
    });
    const wasUpgraded = fromVersion > 0 && toVersion > fromVersion;
    if (wasUpgraded)
      log.info(
        `openAndMigrate: upgraded ${databasePath} from schema version ${fromVersion} to ${toVersion} — index will rebuild on next read`,
      );
    return { db: drizzle({ client }), wasUpgraded };
  } catch (error) {
    try {
      client.close();
    } catch {
    }
    throw error;
  }
};
